      "effect": "suppress-rule",
      "targetRule": "low-insured-mid-spend-approve",
      "onUnknown": "ignore"
    },
    {
      "id": "suppress-low-enhanced-on-prior-enforcement",
      "description": "Prior enforcement prevents D6b enhanced review.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "low-uninsured-mid-spend-enhanced-review",
      "onUnknown": "ignore"
    },
    {
      "id": "suppress-low-moderate-approval-on-prior-enforcement",
      "description": "Prior enforcement prevents D6c approval.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
